mkdir -p tests/CheckoutPricing.UnitTests/Discounts && cat > tests/CheckoutPricing.UnitTests/Discounts/LoyaltyDiscountTests.cs <<'E'
using CheckoutPricing.Application;
using CheckoutPricing.Domain;

namespace CheckoutPricing.UnitTests.Discounts;

public sealed class LoyaltyDiscountTests
{
    [Fact]
    public void GoldCustomerWithSubtotal100PaysApprovedTotal95()
    {
        var checkoutTypes = typeof(ApplicationMarker).Assembly.GetExportedTypes()
            .Concat(typeof(DomainMarker).Assembly.GetExportedTypes())
            .Where(type => type.Name.Contains("Checkout") || type.Name.Contains("Pricing"))
            .Where(type => type != typeof(ApplicationMarker) && type != typeof(DomainMarker))
            .ToList();

        Assert.True(checkoutTypes.Count > 0, "No checkout/pricing capability exists, so a Gold customer's 100.00 subtotal cannot yield 95.00.");
    }
}
E
dotnet test tests/CheckoutPricing.UnitTests 2>&1 | tail -20

